/**
 * Kimyo 10, глава III (§ 3.1–3.21, с. 103–167): уравнения уроков органической лаборатории.
 * Источник — расшифровки docs/textbook/g10-ch3-*.md. Запись — как в учебнике; если в учебнике
 * уравнение не уравнено или химически неверно, здесь верный вариант, а в подсказке — «в учебнике …».
 * Общие схемы с R даны примером из учебника, общая запись — в подсказке.
 */
import type { GradeEq } from './g10g11Equations'

type Tri = readonly [ru: string, en: string, uz: string]

function e(
  id: string,
  topic: Tri,
  left: readonly string[],
  right: readonly string[],
  hint: Tri,
  opts: { cond?: Tri; reversible?: boolean } = {},
): GradeEq {
  const arrow = opts.reversible ? ' ⇄ ' : ' → '
  return {
    id,
    grade: 'g10',
    topicRu: topic[0],
    topicEn: topic[1],
    topicUz: topic[2],
    left,
    right,
    displayRu: `${left.join(' + ')}${arrow}${right.join(' + ')}`,
    conditionsRu: opts.cond?.[0],
    conditionsEn: opts.cond?.[1],
    conditionsUz: opts.cond?.[2],
    hintRu: hint[0],
    hintEn: hint[1],
    hintUz: hint[2],
  }
}

